/// What works on any Material icon (the module beside the `Material` type, as for elements).
module Material =
    /// The filled version (rotation and flips kept). About a third of the icons look the same either
    /// way. An icon that isn't a Material icon comes back unchanged.
    let filled (icon: Icon) : Icon = MaterialData.variant true icon
    /// The outlined version (the default), rotation and flips kept.
    let outlined (icon: Icon) : Icon = MaterialData.variant false icon
    /// An icon from text: a name and options read from the end, separated by '-': filled,
    /// outlined, rotate<degrees>, fliph, flipv ("star-filled-rotate90", "arrow-upward-fliph";
    /// '-' or ' ' in the name means '_'). `Icon.describe` gives text this reads back. Throws an
    /// ArgumentException for a name that isn't a Material icon.
    let icon (text: string) : Icon = MaterialData.fromText text
    /// Like `Material.icon`, but ValueNone for a name that isn't a Material icon.
    let tryIcon (text: string) : Icon voption = MaterialData.tryFromText text
    /// Every icon's name (Google's: lowercase with underscores), in order.
    let names () : string seq = MaterialData.names ()
